def priority(item: float, bins: np.ndarray) -> np.ndarray:
    used = np.min(bins)  # Base used capacity to avoid division by zero
    utilized = bins - used  # Normalize usage relative to minimum capacity
    utilized = np.where(utilized == 0, 1e-9, utilized)
    normalized_utilization = (utilized + item) / bins
    return np.clip(1 - normalized_utilization, 0, 1)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - np.min(bins)  # Avoid division by zero by shifting
    remaining = np.where(remaining == 0, 1e-9, remaining)
    normalized_remaining = (bins - item) / remaining
    return np.clip(normalized_remaining, 0, 1)
